{
  "name": "SLCAN CAN总线接口",
  "name_en": "SLCAN CAN Bus Interface",
  "manufacturer": "",
  "description": "用于通过兼容 SLCAN 协议的串口/CAN 适配器与 CAN 总线设备通信。可在实验系统中完成总线连接打开与关闭、位速率配置、报文发送，以及读取接口版本和序列号等操作，适合连接和调试各类基于 CAN 的实验装置。",
  "description_en": "A CAN bus interface for communicating with CAN devices through an adapter compatible with the SLCAN protocol. In laboratory setups, it is used to open and close the bus connection, configure bitrate, send frames, and read interface version and serial number for connecting and debugging CAN-based experimental equipment.",
  "actions": [
    {
      "action_name": "auto-set_bitrate",
      "description": "设置 CAN 总线位速率，必要时同时设置 CAN FD 数据位速率。",
      "description_en": "Set the CAN bus bitrate and optionally the CAN FD data bitrate."
    },
    {
      "action_name": "auto-set_bitrate_reg",
      "description": "通过 BTR 寄存器值设置自定义 CAN 位时序参数。",
      "description_en": "Set a custom CAN bit timing configuration using the BTR register value."
    },
    {
      "action_name": "auto-flush",
      "description": "清空接口缓冲区中的待处理数据。",
      "description_en": "Flush pending data in the interface buffer."
    },
    {
      "action_name": "auto-open",
      "description": "打开 SLCAN 接口并建立总线通信连接。",
      "description_en": "Open the SLCAN interface and establish bus communication."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 SLCAN 接口连接。",
      "description_en": "Close the SLCAN interface connection."
    },
    {
      "action_name": "auto-send",
      "description": "向 CAN 总线发送一帧报文。",
      "description_en": "Send a message frame onto the CAN bus."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭并停用接口通信会话。",
      "description_en": "Shut down and deactivate the interface communication session."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取底层通信句柄的文件描述符。",
      "description_en": "Get the file descriptor of the underlying communication handle."
    },
    {
      "action_name": "auto-get_version",
      "description": "读取 SLCAN 接口的硬件版本和软件版本。",
      "description_en": "Read the hardware and software version of the SLCAN interface."
    },
    {
      "action_name": "auto-get_serial_number",
      "description": "读取 SLCAN 接口的序列号。",
      "description_en": "Read the serial number of the SLCAN interface."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "SLCAN adapter",
    "serial-to-CAN interface",
    "bitrate configuration",
    "CAN frame transmission",
    "interface version query",
    "serial number identification"
  ]
}

